from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject

class PodStatusDetailsTrsLicensed(SchemaObject):
    plane_type = SchemaField(name="planeType", not_null=True)
    pod_name = SchemaField(name="podName", not_null=True)
    pod_status = SchemaField(name="podStatus", not_null=True)
    capture_status = SchemaField(name="captureStatus", not_null=True)
    file_name = SchemaField(name="fileName")
    file_size = SchemaField(name="fileSize")
    failure_reason = SchemaField(name=" failureReason")

    def __init__(self, plane_type, pod_name, pod_status, capture_status, file_name,
                 file_size, failure_reason):
        self.plane_type = plane_type
        self.pod_name = pod_name
        self.pod_status = pod_status
        self.capture_status = capture_status
        self.file_name = file_name
        self.file_size = file_size
        self.failure_reason = failure_reason
        super(PodStatusDetailsTrsLicensed, self).__init__()


class IPTrafficCaptureStatusTrsLicensed(SchemaObject):
    service_status = SchemaField(name="serviceStatus", not_null=True)
    pod_status = SchemaField(name="podStatus", not_null=True, klass=PodStatusDetailsTrsLicensed, many=True)
    start_time = SchemaField(name="startTime")
    failure_reason = SchemaField(name="failureReason")

    def __init__(self, service_status, pod_status, start_time, failure_reason):
        self.service_status = service_status
        self.pod_status = pod_status
        self.start_time = start_time
        self.failure_reason = failure_reason

        super(IPTrafficCaptureStatusTrsLicensed, self).__init__()
